import React, { useState } from 'react';
import Spline from '@splinetool/react-spline';

export const CONTACT_SPLINE_SCENE =
  process.env.REACT_APP_SPLINE_CONTACT_SCENE ||
  'https://prod.spline.design/LN262OKclnLGMDay/scene.splinecode';

export default function SplineScene() {
  const [ready, setReady] = useState(false);
  const [error, setError] = useState(false);

  return (
    <div className={`mmc-spline-stage${ready ? ' is-ready' : ''}`}>
      {!ready && !error && (
        <p className="mmc-spline-wait">Loading 3D scene…</p>
      )}

      {error && (
        <p className="mmc-spline-error">
          3D scene could not be loaded.
        </p>
      )}

      {!error && (
        <Spline
          scene={CONTACT_SPLINE_SCENE}
          onLoad={() => {
            console.log('Spline loaded');
            setReady(true);
          }}
          onError={(error) => {
            console.error('Spline error:', error);
            setError(true);
          }}
        />
      )}
    </div>
  );
}
